-- Names of the cost centres used by doctors and nurses. Output per row: org|name.
SELECT o.ORGANIZATION_NO||'|'||o.DESCRIPTION_P s FROM {P}ORGANIZATIONS o WHERE o.ORGANIZATION_NO IN (SELECT DISTINCT t.ORGANIZATION_NO FROM {P}PS_STAFF_INTERNAL_TRANSFERS t JOIN {P}PS_STAFF_CONTRACT c ON c.STAFF_ID=t.STAFF_ID AND c.STATUS='A' AND c.CURRENT_CONTRACT='Y' WHERE t.CURRENT_JOB='Y' AND t.STAFF_JOB_ID IN ('098','101','15','150','152','153','154','155','156','157','158','159','160','162','170','171','173','174','192','53','61','102','N','223')) ORDER BY o.ORGANIZATION_NO
